<script src="https://cdn.jsdelivr.net/npm/axios@1.7.9/dist/axios.min.js"></script>
<script>
function toggleAnnouncementTargets(){document.getElementById('announcementTargets').style.display=''}
function announcementIds(value){try{return JSON.parse(value||'[]').map(String)}catch(e){return []}}
function loadTargetDepartments(branchIds,selectedIds){var widget=window.announcementMultiWidgets?.find(w=>w.select.name==='department_ids[]');if(!widget)return;widget.loading();axios.get(@json(route('announcement-target-departments')),{params:{branch_ids:branchIds}}).then(function(response){widget.rebuild(response.data||[],selectedIds||[])}).catch(function(){widget.rebuild([],[]);Swal.fire({icon:'error',title:'Unable to load departments',text:'Please try selecting the branch again.'})})}
function sanitizeAnnouncementHtml(html){var doc=new DOMParser().parseFromString(String(html||''),'text/html'),allowed=new Set(['P','BR','B','STRONG','I','EM','S','UL','OL','LI','BLOCKQUOTE','A','DIV']);[...doc.body.querySelectorAll('*')].forEach(function(node){if(!allowed.has(node.tagName)){node.replaceWith(...node.childNodes);return}var href=node.tagName==='A'?(node.getAttribute('href')||''):'';[...node.attributes].forEach(a=>node.removeAttribute(a.name));if(node.tagName==='A'&&/^(https?:|mailto:)/i.test(href)){node.setAttribute('href',href);node.setAttribute('rel','noopener noreferrer')}});return doc.body.innerHTML}
function openAnnouncement(mode,encoded){var f=document.getElementById('announcementForm'),d=encoded?JSON.parse(atob(encoded)):{};f.reset();f.action=@json(route('organization.store','announcements'));document.getElementById('announcementMethod').innerHTML='';document.getElementById('announcementTitle').textContent=mode==='edit'?'Edit Announcement':'Add New Announcement';['name','category','short_description','content','start_date','end_date'].forEach(k=>f.elements[k].value=d[k]||'');if(window.announcementRichEditor)window.announcementRichEditor.innerHTML=sanitizeAnnouncementHtml(d.content);['is_featured','is_high_priority','is_company_wide'].forEach(k=>f.elements[k].checked=mode==='add'?k==='is_company_wide':Number(d[k])===1);var branchIds=announcementIds(d.branch_ids),departmentIds=announcementIds(d.department_ids);[...f.elements['branch_ids[]'].options].forEach(o=>o.selected=branchIds.includes(o.value));if(mode==='edit'){f.action=@json(route('organization.update',['announcements','__ID__'])).replace('__ID__',d.id);document.getElementById('announcementMethod').innerHTML='<input type="hidden" name="_method" value="PUT">'}window.announcementMultiWidgets?.find(w=>w.select.name==='branch_ids[]')?.refresh();loadTargetDepartments(branchIds,departmentIds);toggleAnnouncementTargets()}
function showAnnouncement(encoded){var d=JSON.parse(atob(encoded)),m=document.getElementById('announcementDetailsModal');[['name',d.name],['category',d.category],['audience',Number(d.is_company_wide)?'Company-wide':'Targeted'],['start',d.start_date],['end',d.end_date||'—'],['description',d.short_description||d.description],['content',d.content||'—']].forEach(x=>m.querySelector('[data-ann="'+x[0]+'"]').textContent=x[1]||'—')}
document.addEventListener('DOMContentLoaded',function(){var field=document.querySelector('.announcement-editor');if(!field||field.nextElementSibling?.classList.contains('ann-rich'))return;var rich=document.createElement('div');rich.className='ann-rich';rich.innerHTML='<div class="ann-rich-toolbar"></div><div class="ann-rich-editor" contenteditable="true" data-placeholder="Write announcement content..."></div>';field.after(rich);var toolbar=rich.querySelector('.ann-rich-toolbar'),editor=rich.querySelector('.ann-rich-editor');window.announcementRichEditor=editor;var tools=[['B','bold','Bold'],['𝐼','italic','Italic'],['S̶','strikeThrough','Strike'],['≡','justifyLeft','Align left'],['≣','justifyCenter','Align center'],['≡','justifyRight','Align right'],['☷','insertUnorderedList','Bulleted list'],['☰','insertOrderedList','Numbered list'],['❞','formatBlock','Quote'],['🔗','createLink','Link'],['⌫','unlink','Remove link'],['↶','undo','Undo'],['↷','redo','Redo'],['‹›','removeFormat','Clear format']];tools.forEach(function(tool){var button=document.createElement('button');button.type='button';button.className='ann-rich-button';button.textContent=tool[0];button.title=tool[2];button.addEventListener('click',function(){editor.focus();if(tool[1]==='createLink'){var url=prompt('Enter link URL');if(url&&/^(https?:|mailto:)/i.test(url))document.execCommand('createLink',false,url)}else if(tool[1]==='formatBlock')document.execCommand('formatBlock',false,'blockquote');else document.execCommand(tool[1],false,null)});toolbar.appendChild(button)});document.getElementById('announcementForm').addEventListener('submit',function(){field.value=sanitizeAnnouncementHtml(editor.innerHTML)})});
document.addEventListener('DOMContentLoaded',function(){window.announcementMultiWidgets=[];document.querySelectorAll('#announcementTargets select[multiple]').forEach(function(select){select.style.display='none';var label=select.closest('.mb-4,div').querySelector('label')?.textContent.trim()||'Options',placeholder='Select '+label.toLowerCase(),wrap=document.createElement('div');wrap.className='ann-multi';wrap.innerHTML='<button type="button" class="form-control ann-multi-button"><span></span><span>⌄</span></button><div class="ann-multi-menu"></div>';select.after(wrap);var caption=wrap.querySelector('button span'),menu=wrap.querySelector('.ann-multi-menu');function addChoice(value,text,selected){var option=document.createElement('option');option.value=String(value);option.textContent=text;option.selected=selected;select.appendChild(option);var row=document.createElement('label');row.className='ann-multi-option';var check=document.createElement('input');check.type='checkbox';check.value=String(value);check.checked=selected;var name=document.createElement('span');name.textContent=text;row.append(check,name);menu.appendChild(row)}var initial=[...select.options].map(o=>({id:o.value,name:o.text,selected:o.selected}));select.innerHTML='';initial.forEach(o=>addChoice(o.id,o.name,o.selected));function selectedValues(){return[...menu.querySelectorAll('input:checked')].map(x=>x.value)}function syncToSelect(){var checked=selectedValues();[...select.options].forEach(o=>o.selected=checked.includes(o.value));caption.textContent=checked.length===0?placeholder:(checked.length===1?select.selectedOptions[0].text:checked.length+' selected')}function refresh(){menu.querySelectorAll('input').forEach(function(check){check.checked=[...select.selectedOptions].some(o=>o.value===check.value)});syncToSelect()}function loading(){caption.textContent='Loading departments...';wrap.querySelector('button').disabled=true}function rebuild(options,selected){select.innerHTML='';menu.innerHTML='';(options||[]).forEach(o=>addChoice(o.id,o.name,(selected||[]).map(String).includes(String(o.id))));wrap.querySelector('button').disabled=false;syncToSelect()}menu.addEventListener('change',function(){syncToSelect();if(select.name==='branch_ids[]')loadTargetDepartments(selectedValues(),[])});wrap.querySelector('button').addEventListener('click',function(){document.querySelectorAll('.ann-multi.open').forEach(x=>{if(x!==wrap)x.classList.remove('open')});wrap.classList.toggle('open')});window.announcementMultiWidgets.push({select:select,refresh:refresh,loading:loading,rebuild:rebuild});refresh()});document.addEventListener('click',function(e){if(!e.target.closest('.ann-multi'))document.querySelectorAll('.ann-multi.open').forEach(x=>x.classList.remove('open'))});toggleAnnouncementTargets();document.querySelectorAll('.ann-confirm').forEach(function(form){form.addEventListener('submit',function(e){if(form.dataset.confirmed)return;e.preventDefault();Swal.fire({title:form.dataset.message,icon:'warning',showCancelButton:true,confirmButtonColor:'#00b783'}).then(function(result){if(result.isConfirmed){form.dataset.confirmed='1';form.submit()}})})});@if($errors->any())new bootstrap.Modal(document.getElementById('announcementModal')).show();@endif});
</script>
<script>
document.addEventListener('DOMContentLoaded',function(){
 document.querySelectorAll('.ann-table form[action*="toggle-status"]').forEach(function(form){form.remove()});
 var calendarIcon='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#718096" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="16" rx="2"></rect><path d="M16 3v4M8 3v4M3 10h18"></path></svg>';
 document.querySelectorAll('.ann-table tbody tr').forEach(function(row){
  row.querySelectorAll('td:nth-child(4)>div').forEach(function(dateRow){
   var date=dateRow.textContent.replace('▣','').trim();
   dateRow.textContent='';
   dateRow.classList.add('d-flex','align-items-center','gap-2');
   dateRow.insertAdjacentHTML('afterbegin',calendarIcon);
   var value=document.createElement('span');value.textContent=date;dateRow.appendChild(value);
  });
 });
});
</script>
<script>
document.addEventListener('DOMContentLoaded',function(){
 var field=document.querySelector('.announcement-editor'),form=document.getElementById('announcementForm');
 if(!field||!form)return;
 field.required=false;
 form.addEventListener('submit',function(event){
  var editor=window.announcementRichEditor;
  field.value=sanitizeAnnouncementHtml(editor?editor.innerHTML:field.value);
  if(!editor||!editor.textContent.trim()){
   event.preventDefault();
   Swal.fire({icon:'error',title:'Content is required',text:'Please write the announcement content.'});
   editor?.focus();
  }
 });
});
</script>
